271	func (c *Controller) updateStatus(vmi *virtv1.VirtualMachineInstance, pod *k8sv1.Pod, dataVolumes []*cdiv1.DataVolume, syncErr common.SyncError) error {
272		key := controller.VirtualMachineInstanceKey(vmi)
273		defer virtControllerVMIWorkQueueTracer.StepTrace(key, "updateStatus", trace.Field{Key: "VMI Name", Value: vmi.Name})
274	
275		hasFailedDataVolume := storagetypes.HasFailedDataVolumes(dataVolumes)
276	
277		// there is no reason to check for waitForFirstConsumer is there are failed DV's
278		hasWffcDataVolume := !hasFailedDataVolume && storagetypes.HasWFFCDataVolumes(dataVolumes)
279		conditionManager := controller.NewVirtualMachineInstanceConditionManager()
280		podConditionManager := controller.NewPodConditionManager()
281	
282		vmiCopy := vmi.DeepCopy()
283		vmiPodExists := controller.PodExists(pod) && !isTempPod(pod)
284		tempPodExists := controller.PodExists(pod) && isTempPod(pod)
285	
286		vmiCopy, err := c.setActivePods(vmiCopy)
287		if err != nil {
288			return fmt.Errorf("Error detecting vmi pods: %v", err)
289		}
290	
291		c.syncReadyConditionFromPod(vmiCopy, pod)
292		if vmiPodExists {
293			var foundImage string
294			for _, container := range pod.Spec.Containers {
295				if container.Name == "compute" {
296					foundImage = container.Image
297					break
298				}
299			}
300			vmiCopy = c.setLauncherContainerInfo(vmiCopy, foundImage)
301	
302			if err := c.syncPausedConditionToPod(vmiCopy, pod); err != nil {
303				return fmt.Errorf("error syncing paused condition to pod: %v", err)
304			}
305	
306			if pod, err = c.syncDynamicAnnotationsAndLabelsToPod(vmiCopy, pod); err != nil {
307				return fmt.Errorf("error syncing annotations and labels to pod: %v", err)
308			}
309	
310		}
311	
312		aggregateDataVolumesConditions(vmiCopy, dataVolumes)
313	
314		if pvc := backendstorage.PVCForVMI(c.pvcIndexer, vmi); pvc != nil {
315			c.backendStorage.UpdateVolumeStatus(vmiCopy, pvc)
316		}
317	
318		if c.clusterConfig.VmiMemoryOverheadReportEnabled() && vmiPodExists {
319			c.updateMemoryOverheadStatusFromPod(vmiCopy, pod)
320		}
321	
322		switch {
323		case vmi.IsUnprocessed():
324			if vmiPodExists {
325				vmiCopy.Status.Phase = virtv1.Scheduling
326			} else if vmi.DeletionTimestamp != nil || hasFailedDataVolume {
327				vmiCopy.Status.Phase = virtv1.Failed
